#!/usr/bin/env python3
"""Aggregate-only report, including paired source-group bootstrap and unit failures."""
import os
os.environ.setdefault('OPENBLAS_NUM_THREADS','2')
import json,re,collections
from pathlib import Path
import numpy as np
ROOT=Path(__file__).resolve().parents[2];OUT=ROOT/'eval/hillclimb';CACHE=ROOT/'data/eval/raw/hillclimb'
def load(name):return json.loads((OUT/name).read_text())
def pct(x):return 'n/a' if x is None else f'{100*x:.2f}%'
def metricrow(m):
 o=m['overall'];return [f"{o['fp']}/{o['human']} ({pct(o['fpRate'])})",f"{o['tp40']}/{o['ai']} ({pct(o['recall40'])})",pct(o['recall60']),f"{o['auroc']:.4f}",str(o['shameFP'])]
def table(headers,rows):return '\n'.join(['| '+' | '.join(headers)+' |','| '+' | '.join(['---']*len(headers))+' |']+['| '+' | '.join(str(x).replace('|','\\|').replace('\n',' ') for x in r)+' |' for r in rows])
def bootstrap():
 before={r['id']:r for r in map(json.loads,(CACHE/'baseline-test.jsonl').read_text().splitlines())}
 groups=collections.defaultdict(lambda:np.zeros(3))
 for row in map(json.loads,(CACHE/'corrected-test.jsonl').read_text().splitlines()):
  if row['label']!='ai' or row.get('family')=='base':continue
  g=groups[row['source_id']];g[0]+=1;g[1]+=int(before[row['id']]['score']>=40);g[2]+=int(row['score']>=40)
 data=np.array(list(groups.values()));rng=np.random.default_rng(20261021);delta=[]
 for _ in range(2000):
  sample=data[rng.integers(0,len(data),len(data))].sum(axis=0);delta.append((sample[2]-sample[1])/sample[0])
 result={'replicates':2000,'seed':20261021,'resamplingUnit':'source_id','deltaRecall40':float((data[:,2].sum()-data[:,1].sum())/data[:,0].sum()),'percentile95':np.quantile(delta,[.025,.975]).tolist()}
 (OUT/'uncertainty.json').write_text(json.dumps(result,indent=2)+'\n');return result

def main():
 b={s:load(f'baseline-{s}.json') for s in ['dev','test','external']};f={s:load(f'corrected-{s}.json') for s in b};initial={s:load(f'final-{s}.json') for s in b}
 proposal=load('proposal.json');perf=load('performance.json');validation=load('validation.json');splits=load('splits.json');entries=json.loads((CACHE/'entries.json').read_text());best=json.loads((CACHE/'best.json').read_text());stats=load('entry-stats.json');byid={r['id']:(r,stats[i],best['weights'][i]) for i,r in enumerate(entries)}
 ci=bootstrap();runs=[json.loads(l) for l in (OUT/'runs.jsonl').read_text().splitlines()];current=[r for r in runs if r.get('entriesSha256')==proposal['entriesSha256']];d=f['test']['overall']['recall40']-b['test']['overall']['recall40']
 criteria=[['RAID-test chat recall ≥ baseline +5 pp',f"+{100*d:.2f} pp",d>=.05],['RAID-test human FP ≤ max(baseline, 1%)',f"{pct(f['test']['overall']['fpRate'])} ≤ {pct(max(.01,b['test']['overall']['fpRate']))}",f['test']['overall']['fpRate']<=max(.01,b['test']['overall']['fpRate'])],['RAID-test every domain human FP ≤2.5%',f"maximum {pct(max(v['fpRate'] for v in f['test']['domain'].values() if v['human']))}",all(v['fpRate'] is None or v['fpRate']<=.025 for v in f['test']['domain'].values())],['External human FP count ≤ baseline',f"{f['external']['overall']['fp']} ≤ {b['external']['overall']['fp']}",f['external']['overall']['fp']<=b['external']['overall']['fp']],['External pooled formal/non-native FP ≤ baseline',f"{f['external']['overall']['hardFP']} ≤ {b['external']['overall']['hardFP']}",f['external']['overall']['hardFP']<=b['external']['overall']['hardFP']],['External shameable FP ≤ baseline',f"{f['external']['overall']['shameFP']} ≤ {b['external']['overall']['shameFP']}",f['external']['overall']['shameFP']<=b['external']['overall']['shameFP']],['External AI recall ≥ baseline',f"{pct(f['external']['overall']['recall40'])} ≥ {pct(b['external']['overall']['recall40'])}",f['external']['overall']['recall40']>=b['external']['overall']['recall40']],['All 12 frozen artifacts score 80','12/12 exactly 80',all(x['score']==80 for x in load('frozen.json'))],['Mean <0.5 ms, worst <1 ms, creation <30 ms',f"{perf['engine-variant']['meanMs']:.3f} / {perf['engine-variant']['worstMs']:.3f} / {perf['engine-variant']['createWorstMs']:.2f} ms",perf['pass']]]
 (OUT/'criteria.json').write_text(json.dumps({'numericBarMet':all(r[2] for r in criteria),'externalUsedOnceForSelection':True,'criteria':[{'criterion':r[0],'result':r[1],'pass':bool(r[2])} for r in criteria]},indent=2)+'\n')
 lines=['# Offline classifier hill-climb report','', 'The inactive corrected proposal meets every requested numerical accuracy and timing criterion. RAID-test chat recall increased from **11.21% to 23.29% (+12.07 percentage points)**; human false positives fell from **28 to 1**. The external check improved both recall and false-positive counts. These results measure this corpus, not authorship certainty or release readiness. A low score never establishes human authorship.','',
 'The first final candidate failed. The permitted single correction selected the highest-recall configuration **already tried on RAID dev with zero dev human false positives**. **The external set was used once for selection.** Only aggregate PLOS and Federal Reserve failures motivated that correction; W&I/AESLC outputs were not used to choose it, refit weights, filter entries, or set a threshold. There was no second search or correction.','',
 '## Baseline versus corrected proposal','',table(['Split / engine','Human FP ≥40','Chat/AI recall ≥40','Recall ≥60','AUROC (unthresholded public score)','Shameable human FP'],[[s+' / '+n,*metricrow(m)] for s in b for n,m in [('baseline',b[s]),('corrected',f[s])]]),'',
 'RAID recall excludes all base/completion models. External recall includes all rows labelled AI, including the disclosed synthetic positives; mixed rows are excluded from both positive and negative denominators. RAID domains are sampled equally on the AI side, so overall and domain-macro recall coincide. AUROC uses the public integer 0–100 score, with ties worth one half.','',
 f"A source-group bootstrap of the cached final test predictions (2,000 replicates, fixed seed) gives a 95% percentile interval of **{100*ci['percentile95'][0]:.2f} to {100*ci['percentile95'][1]:.2f} pp** for the recall improvement. This interval covers sampling variability within RAID, not domain shift.",'',
 '## Criteria','',table(['Criterion','Measured result','Pass'],[[r[0],r[1],'yes' if r[2] else 'NO'] for r in criteria]),'',
 '## Data isolation and reproducibility','',
 f"The CSV was streamed with Python csv.field_size_limit raised. SHA-256: `{splits['csvSha256']}`. Keep 30–600 whitespace words. Split by `sha256('slop-hillclimb-v1:'+source_id)[:16] % 100`: train <60, dev 60–79, test ≥80. All eligible humans are kept after external exclusions. Human/AI texts from one source remain together. Excluded {splits['excludedExternalIds']:,} external RAID row IDs and all {splits['excludedExternalSources']:,} represented source groups ({splits['excludedRows']:,} eligible CSV rows), including parallel generations.",'',
 table(['Split','Human','Chat AI','Base AI, informational','Source groups'],[[s,v['labels'].get('human',0),v['labels'].get('chat',0),v['labels'].get('base',0),v['sources']] for s,v in splits['splits'].items()]),'',
 'Chat targets: gpt4, chatgpt, cohere-chat, llama-chat, mistral-chat, mpt-chat. Base models never enter train fitting or the objective. Each observed domain × model × decoding × penalty stratum keeps the lowest deterministic row hashes: at most 200 train / 75 dev / 75 test. Base rows have a separate 12-row stratum cap for informational dev/test results. Models with four released settings therefore have more sampled rows than those with two; per-model results below expose that imbalance.','',
 'Training balances classes and domains, and gives equal mass to observed generator/decoding/penalty strata. Sampling without repetition penalty occupies six of eighteen chat strata (one third), rather than dominating by row count or repetition. Presence is binary, so repeating one phrase a thousand times creates one feature. There is no human-source pretraining corpus or external-corpus fit.','',
 'The baseline was snapshotted from the dirty working tree, not HEAD: 77 registered first-party rules. Baseline dev/test/external each ran once. No test features were extracted. The test remained unused throughout the climb. Test and external each had one first-final pass and one corrective-final pass under the explicit correction exception; `correction.json` records this departure from the nominal baseline-plus-one-final protocol. No third candidate was evaluated. All locks and predictions are in the ignored cache.','',
 f"Engine snapshot digest: `{proposal['engineSha256']}`. Current proposal digest: `{proposal['packSha256']}`. Vite SSR loads immutable snapshot public APIs; baseline and final use `analyzePost({{text}})`. Dev span replay reproduced every baseline score and Shame decision; the corrected public API matched all threshold and Shame counts. QA found and fixed a zero-word replay early-return mismatch on one punctuation-only dev generation; no threshold or Shame gate changed. All final corrected dev scores now replay exactly. Public results, including AUROC, are authoritative. See `replay.json`.",'',
 '## Measurement and search','',
 f"The feature pool has {len(entries):,} features: all 77 first-party rules, every surviving vendor matcher, and safe literal/bounded-regex dropped candidates. {load('candidates.json')['literals']:,} recovered/kept literals and {load('candidates.json')['regexes']} regexes are compiled in one production compilePhrases pass, alongside first-party raw custom outputs. Conditional riders/triggers and regex safety rejections are excluded; human-control hits, ordinary phrases, topic words and milestones are measured rather than rejected by judgment. Protected example spans are excluded from binary presence, while complete raw spans remain in the private replay cache.",'',
 'Two train-only approaches were compared: (1) Jeffreys-smoothed AI/human log-rate ratios minus 1.28/1.645/1.96 standard errors, with support 10/25/50; (2) sparse nonnegative logistic regression using scipy L-BFGS-B with L1/L2 penalties. Coefficients below 0.01 are removed. Both require positive lift in at least 60% of supported domains and at least two released chat-model families. Domain support means at least eight combined hits; model support means at least five AI hits. Rare single-domain cues remain a risk.','',
 'The logistic fit uses binary first-party rule presence plus dictionary presence. Correlation is addressed jointly. Runtime retains the production span competition, category caps, repeats and style support; dev rescoring therefore uses the real scorer rather than treating a linear prediction as an engine score. Logistic intercepts stay offline. Nonnegative coefficients are scaled/capped to evidence points and the existing ≥40 boundary is calibrated by exact dev rescoring (rounded score 40 starts at approximately 6.03 evidence points with K=12).','',
 f"All {len(runs)} attempted configurations are logged in runs.jsonl; {len(current)} use the final formatting-evidence semantics. Earlier exploratory runs incorrectly treated a recovered format cue as phrase evidence; that was corrected before any final selection. Knobs tried: estimator, confidence, support, L1/L2 strength, common weight scale, per-rule cap, and style scale. K=12, style-only ceiling 39, existing category caps, and fingerprint floor 80 are unchanged. The selected corrected configuration is `{proposal['id']}` (L1=0.00003, L2=0.0001, scale=1, cap=3). The stronger maximum-recall dev choice and its failed final metrics remain in final-*.json; corrected-*.json are the delivered proposal.",'',
 'The optional Google Books Ngram baseline was absent at fitting and the last pre-final check. It did not influence the proposal. The likelihood fitter can consume exact/upper-bound token rates as 20-document human pseudo-counts using `1-exp(-rate*mean_document_words/1e6)`; unavailable phrases are not treated as observed. The logistic fits currently use RAID alone. The file arrived by the completion audit (see audit.json), after the frozen proposal had been evaluated. It did not help this run. Using it now requires a new, separately isolated experiment; it cannot be used to reopen this test.','']
 for method in ['llr','logistic']:
  eligible=[r for r in current if r['method']==method and r['passed']]
  x=max(eligible,key=lambda r:r['metrics']['macroRecall40'])
  lines+= [f"Best dev-feasible {method}: {pct(x['metrics']['overall']['recall40'])} recall, {x['metrics']['overall']['fp']} human FP; `{x['id']}`.",'']
 lines+=['## First final failure and single correction','',table(['Split','First-final human FP','First-final AI recall ≥40','Corrected human FP','Corrected AI recall ≥40'],[[s,initial[s]['overall']['fp'],pct(initial[s]['overall']['recall40']),f[s]['overall']['fp'],pct(f[s]['overall']['recall40'])] for s in b]),'',
 'The first final had 16 PLOS FP versus baseline 6, and 6 Federal Reserve FP versus baseline 0. Repeated institutional templates and formal vocabulary generalized poorly despite meeting original dev gates. The correction tightened the dev false-positive budget to zero and selected from existing runs, without examining or copying any external text or retuning to the restricted sources. External results are no longer an untouched estimate for the final selection, and no further correction is permitted.','']
 for split in b:
  lines += [f'## {split.title()} breakdowns','']
  for field in ['domain','model','length','decoding','repetition_penalty']+(['source','subset'] if split=='external' else []):
   groups=sorted(set(b[split][field])|set(f[split][field]));rows=[]
   for key in groups:
    old=b[split][field][key];new=f[split][field][key]
    rows.append([key,f"{old['fp']} → {new['fp']} / {new['human']}",f"{pct(old['recall40'])} → {pct(new['recall40'])} ({new['ai']})",f"{pct(old['recall60'])} → {pct(new['recall60'])}",f"{old['shameFP']} → {new['shameFP']}"])
   lines += [f'### By {field}','',table(['Group','Human FP before → after / N','AI recall ≥40 before → after (N)','Recall ≥60 before → after','Shameable FP'],rows),'']
  if split!='external':
   lines += ['### Base/completion models (informational only)','',table(['Model','N','Recall ≥40 baseline → corrected'],[[k,v['base'],pct(v['baseRecall40'])+' → '+pct(f[split]['model'][k]['baseRecall40'])] for k,v in b[split]['model'].items() if v['base']]),'']
 # Contributions come from held-in dev only, no external examples/attributions inspected.
 top=load('dev-contributions.json')
 top=[x for x in top if x['id'].startswith('measured.')][:20]
 lines+=['## Top contributing measured cues','', 'Ranked by counted evidence points across chat-AI dev documents. These are co-occurring contributions, not causal ablations. Matcher strings below come from the dictionary inventory, not dataset quotations.','',table(['Matcher / rule','Points','Train human hits / N','Train AI hits / N','Dev AI posts','Counted AI points'],[[str(byid[x['id']][0].get('phrases') or byid[x['id']][0].get('patterns')),byid[x['id']][2],f"{byid[x['id']][1]['human']}/7166",f"{byid[x['id']][1]['ai']}/28800",x['aiPosts'],f"{x['aiPoints']:.1f}"] for x in top]),'']
 recovered=[(r,st,w) for r,st,w in byid.values() if w and any(o['state']=='dropped' for o in r.get('origins',[]))];recovered.sort(key=lambda x:-x[2]);rejected=[(r,st) for r,st,w in byid.values() if not w and any(o['state']=='kept' for o in r.get('origins',[]))];rejected.sort(key=lambda x:-x[1]['ai'])
 lines+=['## Guesswork reversed','',f"{len(recovered)} selected features include a previously dropped origin; {len(rejected)} surviving-vendor features receive zero weight. Duplicates may have both kept and dropped origins. Entries absent from this RAID sample receive no coefficient even if the dictionary sounds plausible. Per-entry and per-domain/model train counts are in entry-stats.json; the generated pack includes compact counts and source provenance.",'',table(['Previously dropped matcher','Prior reason(s)','Now points','Train human / AI hits'],[[str(r.get('phrases') or r.get('patterns')),', '.join(sorted(set(o.get('reason','').split(':')[0] for o in r['origins'] if o['state']=='dropped'))),w,f"{st['human']} / {st['ai']}"] for r,st,w in recovered[:18]]),'',table(['Previously kept matcher, now zero','Train human / AI hits'],[[str(r.get('phrases') or r.get('patterns')),f"{st['human']} / {st['ai']}"] for r,st in rejected[:18]]),'',
 'First-party examples removed or downweighted include social-closer and formulaic-opener rules, generic transitions, emoji/hashtag/bypass cues and several narrative tropes. Explicit fingerprints retain their original weights regardless of sample support. This preserves rare explicit artifacts but regresses some earlier hand-written synthetic expectations; those tradeoffs are visible in validation.','',
 '## Performance and scratch validation','',table(['Engine','Mean analyze','p95','Worst single call','Worst engine creation'],[[k,f"{v['meanMs']:.3f} ms",f"{v['p95Ms']:.3f} ms",f"{v['worstMs']:.3f} ms",f"{v['createWorstMs']:.2f} ms"] for k,v in perf.items() if isinstance(v,dict)]),'',
 'Timing used 200 different 300-whitespace-word excerpts from dev (100 human, 100 chat AI), 2,500 warm calls, explicit GC before timing, then five calls per input (1,000 calls). Reported worst is the actual maximum call, not a median or trimmed tail. Engine creation includes every selected rule and takes the maximum of 40 creations. Import/transpilation is excluded. Baseline and proposal ran serially; these Node timings do not certify Chromium or future machine contention.','',
 'The proposal was applied to an isolated temporary copy of the current dirty checkout with the frozen engine snapshot, using proposal.patch. No worktree/checkout source files were changed. `pnpm check` passed with zero errors/warnings. `pnpm test --maxWorkers=2` finished with **35 failures, 562 passes, 1 skipped** in **6 failing files**. The temporary copy was removed. These failures are not silently waived; the proposal is not ready to activate.','',
 'Failures fall into changed first-party rule-presence/weight expectations, synthetic recall and score floors, one ordinary checklist scoring 27 where a previous guardrail required <20 (although still below the ≥40 flag threshold), and tests assuming exactly ten packs/a fixture for every registered pack. API-level absence of formerly active weak bypass evidence also fails expectations. Engine compiler/context/score contracts, vendor checks, non-engine tests, and all 12 explicit fingerprints remain intact. All individual failing assertions are listed in VALIDATION.md without dataset text.','',
 '## Risks and limits','',
 '- RAID topic/domain correlation can turn genre words into signals. Per-domain consistency mitigates but does not remove it. Poetry and reviews differ from professional social posts. Models with more released decoding settings have more sampled rows; report per-model results rather than interpreting pooled recall as a market share estimate.',
 '- RAID is dominated by 2023-era model generations and prompt continuations; it does not establish performance on contemporary reasoning models, paraphrasing, editing or adversarial attacks. The small external modern-model set and synthetic positives are heterogeneous.',
 '- There is no provenance-verified LinkedIn-style human cohort. W&I learner essays and formal controls expose some risks but are evaluation only. Institutional releases are correlated; dozens of hits may describe one repeated template.',
 '- The external set was used once for the permitted correction. A fresh independent release holdout is needed. The corrective-final evaluation is an explicit exception to the nominal single-final locked-test count; audit receipts preserve both candidates.',
 '- Zero observed FP on dev and one on test do not imply zero population FP. Editorial score values are not calibrated authorship probabilities. Lower scores cannot be used as human-authorship claims.',
 '- The dictionary Markdown separator row was inadvertently ingested as an extra `---` matcher (0.97 points, six human and 109 AI train presences). It remains in the frozen proposal to preserve the locked experiment and is documented as a harness artifact, not a licensed upstream entry. The parser now excludes Markdown delimiters by default; an explicit legacy compatibility option preserves v1 reproducibility and cache hashes reject silent changes. Audit its classification/provenance before activation; no post-final tuning or hidden result replacement was performed.',
 '- Nonnegative logistic weights are not causal language markers. Correlated candidate lists, rare support and pre-existing vocabulary rules can still overlap. Historical search logs include one below-threshold score discrepancy on a zero-word punctuation-only generation. The replay now honors the public early return; no gate or proposal weight changed.',
 '- W&I and AESLC licences prohibit using their data or derived information to build product data. They were final checks only and never entered feature extraction, fitting or selection. Outputs are aggregate only. Do not treat this report as commercial-use permission.',
 '- Statistical weights are numbers derived from RAID text. RAID repository code is MIT, but underlying books/news/reviews/Reddit rights are mixed and not independently cleared. No text is bundled or redistributed; provenance and numeric derivation do not settle rights to product use.',
 '- Unit regressions remain, including a human-style below-40 score guardrail. This is an experimental proposal, not a recommendation to register it without review.','',
 '## Files and reproduction','', 'See README.md for commands, lock behavior and the single-correction workflow. Existing engine/test/eval-lib files, INTENTIONS.md and HANDOFF.md were not edited; no commit, push, browser or network call was made. All corpus text, spans, row-level predictions, engine copies and logs remain under ignored data/eval/raw/hillclimb/.','',
 'New source proposal: `src/lib/engine/packs/measured/index.ts` (not registered). Activation patch: `eval/hillclimb/proposal.patch` (registry import and reweighting only; no score.ts or index.ts algorithm change).','',
 table(['New artifact group','Files'],[['Harness','prepare.py; common.mjs; baseline.mjs; parse-drops.mjs; features.mjs; fit.py; climb.mjs; proposal.mjs; final.mjs; correct.mjs; benchmark.mjs; validate.py; diagnostics.mjs; report.py; run.mjs; harness.test.mjs'],['Docs','README.md; REPORT.md; PROGRESS.md; VALIDATION.md'],['Aggregate inventories','splits.json; candidates.json; entry-stats.json; dev-contributions.json; runs.jsonl; proposal.json; best-dev.json; correction.json; external-inputs.json; replay.json; audit.json'],['Aggregate outcomes','baseline-{dev,test,external}.json; final-{dev,test,external}.json (failed first final); corrected-{dev,test,external}.json (delivered); initial-{proposal,performance,validation}.json; performance.json; validation.json; frozen.json; uncertainty.json; criteria.json']]),'']
 (OUT/'REPORT.md').write_text('\n'.join(lines))
 log=(CACHE/'validation-test.log').read_text();failures=[]
 for line in log.splitlines():
  if line.startswith(' FAIL '):
   name=re.sub(r':.*$',': [parameter omitted]',line.strip()[5:])
   failures.append(name)
 validation['counts']={'failed':35,'passed':562,'skipped':1,'failedFiles':6}
 (OUT/'validation.json').write_text(json.dumps(validation,indent=2)+'\n')
 (OUT/'VALIDATION.md').write_text('# Scratch proposal validation\n\n`pnpm check`: 0 errors, 0 warnings. `pnpm test --maxWorkers=2`: 35 failed, 562 passed, 1 skipped; 6 failed files. Scratch copy removed. No existing tests changed.\n\nThe failures are real proposal regressions or assumptions about the old ten-pack inventory. They were not used to tune the proposal after final evaluation.\n\n- '+'\n- '.join(failures)+'\n\nReasons: inactive first-party rules no longer emit expected signals; altered evidence weights change old score/tier thresholds and obvious-synthetic recall (56.25% vs required 90%); extra measured pack lacks a hand-written pack fixture and changes the ten-pack count. One checklist reaches 27, exceeding its former <20 guardrail. Explicit fingerprints still meet 80. Detailed logs remain in the ignored cache.\n')
 print('Report written; numerical bar',all(r[2] for r in criteria),'95% recall delta CI',ci['percentile95'])
if __name__=='__main__':main()
